function metadata_run(string $file,array $args,string $root):string{$pipes=[];$p=proc_open(array_merge([PHP_BINARY,$root.'/'.$file],$args),[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$root);if(!is_resource($p))throw new RuntimeException('Could not start disposable schema utility');fclose($pipes[0]);$out=stream_get_contents($pipes[1]);fclose($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[2]);if(proc_close($p)!==0)throw new RuntimeException($err?:'Disposable schema utility failed');return$out;}
