 $outer=[['latitude'=>14.8000,'longitude'=>121.0000],['latitude'=>14.8000,'longitude'=>121.0040],['latitude'=>14.8040,'longitude'=>121.0040],['latitude'=>14.8040,'longitude'=>121.0000]];
 $inner=[['latitude'=>14.8010,'longitude'=>121.0010],['latitude'=>14.8010,'longitude'=>121.0030],['latitude'=>14.8030,'longitude'=>121.0030],['latitude'=>14.8030,'longitude'=>121.0010]];
 $old=save_zone($pdo,['site_id'=>'pup','name'=>'pre-011 legacy polygon','is_demo'=>true,'vertices'=>$outer]);metadata_assert(count($old['rings'])===1&&$old['margin_m']===null,'pre-011 schema still saves old single-ring payload and reads null metadata');
 $before=(int)$pdo->query("SELECT COUNT(*) FROM safe_zones WHERE site_id='pup'")->fetchColumn();$missingRejected=false;try{save_zone($pdo,['site_id'=>'pup','name'=>'metadata too early','is_demo'=>true,'vertices'=>$outer,'gpx_file_name'=>'track.gpx','margin_m'=>10]);}catch(InvalidArgumentException $e){$missingRejected=str_contains($e->getMessage(),'migration 011');}
