 $rings=[array_map(fn($p)=>[(float)$p['latitude'],(float)$p['longitude']],$outer),array_map(fn($p)=>[(float)$p['latitude'],(float)$p['longitude']],$inner)];$filledClassifier=fn(float $lat,float $lng,array $geometry):bool=>point_in_polygon($lat,$lng,$geometry[0]??[]);$rowsBefore=(int)$pdo->query("SELECT COUNT(*) FROM safe_zones WHERE site_id='pup'")->fetchColumn();$filledRejected=false;try{save_zone($pdo,['site_id'=>'pup','name'=>'filled loop rejected','is_demo'=>true,'rings'=>[$outer,$inner]],$filledClassifier);}catch(SafeZoneLoopGuardException $e){$filledRejected=str_contains($e->getMessage(),'must classify OUTSIDE');}
