 $saved=save_zone($pdo,['site_id'=>'pup','name'=>'metadata corridor','is_demo'=>true,'rings'=>[$outer,$inner],'margin_m'=>10,'gpx_file_name'=>'oval-lane.gpx','gpx_point_count'=>3000,'simplified_point_count'=>240,'simplify_tolerance_m'=>2.5,'simplify_max_deviation_m'=>2.4,'recorded_track_length_m'=>1200.5,'ground_length_m'=>1180.25,'recording_note'=>'Recorded with the phone app']);
 metadata_assert(count($saved['rings'])===2&&$saved['margin_m']===10.0&&$saved['gpx_file_name']==='oval-lane.gpx'&&$saved['gpx_point_count']===3000&&$saved['simplified_point_count']===240&&$saved['simplify_tolerance_m']===2.5&&$saved['simplify_max_deviation_m']===2.4&&$saved['recorded_track_length_m']===1200.5&&$saved['ground_length_m']===1180.25&&$saved['recording_note']==='Recorded with the phone app','all two-ring safe-zone metadata fields round-trip');metadata_assert($saved['corridor_width_m']===20.0&&$saved['recorded_minus_ground_difference_m']===20.25,'safe-zone API data includes derived corridor width and recorded-minus-ground difference');
 foreach(['gpx_point_count'=>-1,'recorded_track_length_m'=>-0.1] as $key=>$bad){$invalid=false;try{save_zone($pdo,['site_id'=>'pup','name'=>'invalid metadata','is_demo'=>true,'vertices'=>$outer,$key=>$bad]);}catch(InvalidArgumentException $e){$invalid=true;}metadata_assert($invalid,"negative $key is rejected");}
 $invalidMargin=false;try{save_zone($pdo,['site_id'=>'pup','name'=>'invalid GPX margin','is_demo'=>true,'vertices'=>$outer,'gpx_file_name'=>'track.gpx','margin_m'=>4]);}catch(InvalidArgumentException $e){$invalidMargin=true;}metadata_assert($invalidMargin,'GPX margin below 5 m is rejected');
 echo "PASS safe-zone metadata scratch integration complete; disposable database only.\n";
